<?php
declare(strict_types=1);namespace Pam\Native\Observability;use InvalidArgumentException;final readonly class ObservabilityConfig{public function __construct(public string$endpoint,public string$serviceName,public string$serviceVersion='0.0.0',public float$sampleRate=1.0,public int$batchSize=64,public int$maxQueue=1024,public int$timeoutMillis=5000,public array$headers=[]){if(filter_var($endpoint,FILTER_VALIDATE_URL)===false||!str_starts_with($endpoint,'https://'))throw new InvalidArgumentException('Telemetry endpoint must use HTTPS.');if(!preg_match('/^[A-Za-z0-9._-]{1,128}$/D',$serviceName)||$sampleRate<0||$sampleRate>1||$batchSize<1||$batchSize>512||$maxQueue<$batchSize||$maxQueue>10000||$timeoutMillis<100||$timeoutMillis>30000)throw new InvalidArgumentException('Invalid observability configuration.');foreach($headers as$k=>$v)if(!is_string($k)||!is_string($v)||preg_match('/^[A-Za-z0-9-]+$/D',$k)!==1||str_contains($v,"\r")||str_contains($v,"\n"))throw new InvalidArgumentException('Invalid telemetry header.');}}
